        answer: `**Класс** — шаблон (описание), на основе которого создаются объекты. Класс определяет состояние (поля) и поведение (методы). Класс — это тип данных, описывающий общие характеристики множества однотипных объектов.

**Объект** — экземпляр класса, конкретная сущность, обладающая:

- **состоянием** — значениями полей;
- **поведением** — методами;
- **идентичностью** — уникальностью среди других объектов.

**Интерфейс** — контракт, определяющий набор методов, которые обязан реализовать класс. Интерфейс описывает, **что** должен делать объект, но не **как**. В Java класс может реализовывать множество интерфейсов, что обеспечивает множественное наследование типа.

\`\`\`java
interface Movable {
    void move();
}

class Car implements Movable {
    @Override
    public void move() { System.out.println("Car is moving"); }
}

Movable car = new Car(); // объект car — экземпляр класса Car
\`\`\``,
