        question: 'Что такое Metaspace и чем он отличается от PermGen?',
        answer: `И **PermGen**, и **Metaspace** хранят **метаданные классов** (структуру классов, методы, пул констант рантайма). Разница — где и как:

**PermGen (Permanent Generation)** — до Java 7 включительно:

- часть **кучи (heap)** фиксированного размера (\`-XX:MaxPermSize\`);
- частая причина \`OutOfMemoryError: PermGen space\`, особенно при активной загрузке классов (перезагрузки приложений в сервере, генерация прокси);
- размер трудно подобрать заранее.

**Metaspace** — начиная с Java 8 (заменил PermGen):

- находится в **нативной (off-heap) памяти**, а не в куче;
- **растёт автоматически** по умолчанию, ограничен доступной ОС-памятью (можно ограничить \`-XX:MaxMetaspaceSize\`);
- строковый пул и статические поля при этом переехали в обычную кучу ещё раньше.

Итог: переход на Metaspace убрал самую частую причину PermGen-ошибок, но утечка классов (например, при неправильной выгрузке ClassLoader’ов) всё ещё может дать \`OutOfMemoryError: Metaspace\`.`,
