        id: 'memory-leaks',
        question: 'Что такое утечка памяти в Java, если есть сборщик мусора? Как её найти?',
        answer: `Несмотря на GC, **утечка памяти** в Java возможна: это объекты, которые **больше не нужны, но остаются достижимыми** от GC Roots, поэтому сборщик их не удаляет. Память растёт, пока не наступит \`OutOfMemoryError\`.

Типичные причины:

- объекты, накапливаемые в **статических коллекциях** или синглтонах и никогда не удаляемые;
- **незакрытые ресурсы** (потоки, соединения, стримы) — использовать try-with-resources;
- **\`ThreadLocal\`** в пуле потоков без \`remove()\` — значение живёт, пока жив поток пула;
- слушатели/колбэки, которые забыли отписать (объект держится подписчиком);
- ключи в \`HashMap\` с некорректным \`equals/hashCode\` (нельзя удалить), кэши без ограничения размера/TTL.

Как искать:

1. симптомы — растущее потребление heap, учащающиеся Full GC, в итоге \`OutOfMemoryError: Java heap space\`;
2. снять **heap dump** (\`-XX:+HeapDumpOnOutOfMemoryError\`, \`jmap\`) и анализировать в **Eclipse MAT** / VisualVM — искать доминаторы и цепочки ссылок, удерживающие объекты (path to GC Roots);
3. мониторить память в проде (JFR, Micrometer/Grafana), профилировать под нагрузкой.

Профилактика: ограниченные кэши, аккуратная работа с ThreadLocal и ресурсами, слабые ссылки (\`WeakHashMap\`) где уместно.`,
