        answer: `**Абстрактный класс:**

- может иметь состояние (поля любых модификаторов);
- может иметь конструкторы;
- методы любых модификаторов доступа;
- класс наследует только один абстрактный класс (\`extends\`);
- семантика: «является» — общая база для родственных классов.

**Интерфейс:**

- состояния нет — только \`public static final\` константы;
- конструкторов нет;
- методы: abstract, \`default\`, \`static\` (Java 8+), \`private\` (Java 9+);
- класс может реализовать много интерфейсов (\`implements\`);
- семантика: «умеет» — контракт поведения для несвязанных классов.

**Когда что выбирать:**

- интерфейс — по умолчанию: описание способности (\`Comparable\`, \`Serializable\`);
- абстрактный класс — когда нужно общее состояние, защищённые методы или частичная реализация (Template Method).

С появлением default-методов граница размылась, но ключевое отличие осталось: **состояние и конструкторы есть только у классов**.`,
