        question: 'Что такое дженерики (Generics) и стирание типов (Type Erasure)?',
        answer: `**Дженерики** — механизм параметризации типов (Java 5): классы и методы работают с разными типами, сохраняя типобезопасность на этапе компиляции.

\`\`\`java
List<String> list = new ArrayList<>();
list.add("ok");
list.add(42); // ошибка компиляции — не ClassCastException в runtime

<T extends Comparable<T>> T max(List<T> list) { ... } // обобщённый метод
\`\`\`

**Type Erasure (стирание типов)** — информация о параметрах типа удаляется при компиляции: \`List<String>\` и \`List<Integer>\` в байт-коде — один \`List\`. Сделано для обратной совместимости с кодом до Java 5.

Следствия стирания:

- нельзя: \`new T()\`, \`new T[]\`, \`instanceof List<String>\`, перегрузка по параметру типа;
- примитивы не поддерживаются (только обёртки).

**Wildcards:**

- \`List<?>\` — любой тип;
- \`List<? extends Number>\` — Number и наследники (чтение — producer);
- \`List<? super Integer>\` — Integer и предки (запись — consumer).

Правило **PECS**: Producer — Extends, Consumer — Super.`,
