        answer: `**String Pool** — область в куче, где JVM кэширует строковые литералы. Одинаковые литералы указывают на один объект — экономия памяти (возможна благодаря неизменяемости String).

\`\`\`java
String a = "hello";            // из пула
String b = "hello";            // та же ссылка из пула
String c = new String("hello"); // НОВЫЙ объект в куче

a == b;        // true  — один объект из пула
a == c;        // false — разные объекты
a.equals(c);   // true  — одинаковое содержимое
c.intern() == a; // true — intern() возвращает экземпляр из пула
\`\`\`

**Разница:**

- \`==\` сравнивает **ссылки** (один ли это объект в памяти);
- \`equals()\` сравнивает **содержимое** посимвольно.

Правила: строки всегда сравнивать через \`equals()\`; для защиты от NPE — \`"literal".equals(variable)\` или \`Objects.equals(a, b)\`; не использовать \`new String("...")\`.`,
