        answer: `**\`record\`** (Java 16) — компактный способ объявить **неизменяемый носитель данных**. Компилятор сам генерирует \`private final\`-поля, конструктор, геттеры (\`name()\`, а не \`getName()\`), \`equals()\`/\`hashCode()\` (по всем компонентам) и \`toString()\`:

\`\`\`java
public record Point(int x, int y) {}
\`\`\`

Особенности: record **финальный** и **не может наследоваться** от класса (неявно наследует \`java.lang.Record\`), но может реализовывать интерфейсы. Можно добавить компактный конструктор для валидации. Подходит для DTO, ключей, value-объектов.

**\`sealed\`-класс/интерфейс** (Java 17) — ограничивает, **какие классы могут его наследовать/реализовывать**, через \`permits\`:

\`\`\`java
public sealed interface Shape permits Circle, Square {}
\`\`\`

Наследники обязаны быть \`final\`, \`sealed\` или \`non-sealed\`. Зачем: контроль над иерархией (закрытое множество вариантов) и **исчерпывающий** \`switch\` по типам без \`default\` — компилятор знает все подтипы. Вместе record + sealed дают в Java алгебраические типы данных и удобны с pattern matching.`,
