        id: 'reflection',
        question: 'Что такое Reflection API и где он применяется?',
        answer: `**Reflection (рефлексия)** — механизм, позволяющий **исследовать и изменять** структуру классов во время выполнения: получать список полей, методов, конструкторов, аннотаций, создавать объекты и вызывать методы по имени, не зная типа на этапе компиляции.

\`\`\`java
Class<?> clazz = obj.getClass();
Method m = clazz.getDeclaredMethod("hello");
m.setAccessible(true); // доступ к private
m.invoke(obj);
\`\`\`

Доступ к **приватным** членам открывается через \`setAccessible(true)\` (если не запрещено модульной системой/менеджером безопасности).

Где применяется: фреймворки и библиотеки — Spring (DI, создание бинов, обработка аннотаций), Hibernate (маппинг сущностей), Jackson/Gson (сериализация), JUnit (поиск тестовых методов).

Минусы: **медленнее** прямых вызовов, обходит проверки типов и инкапсуляцию (риск ошибок в рантайме вместо компиляции), усложняет рефакторинг и анализ кода. Поэтому в прикладном коде рефлексию используют осторожно — в основном она «спрятана» внутри фреймворков.`,
