        question: 'Как работает Cloneable и почему его лучше избегать? Как ещё копировать объекты?',
        answer: `**\`Cloneable\`** — маркерный интерфейс, включающий поведение \`Object.clone()\` (без него \`clone()\` бросит \`CloneNotSupportedException\`). \`clone()\` создаёт побитовую копию объекта.

Почему его избегают (в т.ч. по «Effective Java»):

- **\`clone()\` делает поверхностную (shallow) копию** — вложенные объекты и коллекции остаются общими у оригинала и копии, что ведёт к скрытым багам; для глубокой копии \`clone()\` надо переопределять вручную;
- **сломанный контракт**: \`clone()\` объявлен в \`Object\` (а не в \`Cloneable\`), \`protected\`, бросает checked-исключение, не вызывает конструктор — механизм неинтуитивен и легко реализуется неверно;
- плохо работает с \`final\`-полями.

Предпочтительные альтернативы:

- **конструктор копирования**: \`new ArrayList<>(other)\`, \`public Point(Point p)\`;
- **статический фабричный метод** копирования;
- для record — создать новый через компоненты;
- для глубокой копии — копировать поля вручную или через сериализацию/специализированные библиотеки.

Итог: конструктор/фабрика копирования проще, безопаснее и явнее, чем \`Cloneable\`.`,
