        answer: `**ACID** — четыре свойства транзакций реляционных БД:

- **Atomicity (атомарность)** — транзакция выполняется целиком или не выполняется вовсе. При сбое все изменения откатываются (rollback).
- **Consistency (согласованность)** — транзакция переводит БД из одного согласованного состояния в другое; все ограничения (constraints, foreign keys) соблюдены.
- **Isolation (изоляция)** — параллельные транзакции не влияют друг на друга; результат как при последовательном выполнении (степень зависит от уровня изоляции).
- **Durability (долговечность)** — после подтверждения (commit) изменения сохраняются даже при сбое системы (обеспечивается WAL — write-ahead logging).

Противоположный подход — **BASE** (Basically Available, Soft state, Eventually consistent) — используется в распределённых NoSQL-системах, где важнее доступность.`,
