        id: 'isolation-levels',
        question: 'Какие уровни изоляции транзакций вы знаете?',
        answer: `Уровни изоляции (от слабого к строгому) и аномалии, которые они допускают:

| Уровень | Dirty Read | Non-Repeatable Read | Phantom Read |
|---|---|---|---|
| READ UNCOMMITTED | да | да | да |
| READ COMMITTED | нет | да | да |
| REPEATABLE READ | нет | нет | да* |
| SERIALIZABLE | нет | нет | нет |

**Аномалии:**

- **Dirty read** — чтение незафиксированных изменений другой транзакции;
- **Non-repeatable read** — повторное чтение той же строки даёт другой результат (другая транзакция изменила и закоммитила);
- **Phantom read** — повторный запрос по условию возвращает новые строки, добавленные другой транзакцией.

\\* В MySQL (InnoDB) REPEATABLE READ предотвращает фантомы через next-key locking; в PostgreSQL — через снапшоты (MVCC).

По умолчанию: PostgreSQL, Oracle — READ COMMITTED; MySQL — REPEATABLE READ.`,
