        answer: `**SQL (реляционные)** — PostgreSQL, MySQL, Oracle:

- строгая схема (таблицы, столбцы, типы);
- ACID-транзакции;
- мощный язык запросов (JOIN, агрегации);
- вертикальное масштабирование (проще), горизонтальное — сложнее.

**NoSQL** — разные модели данных:

- **документные** (MongoDB) — JSON-документы, гибкая схема;
- **key-value** (Redis) — кэши, сессии, максимальная скорость;
- **колоночные** (Cassandra) — большие объёмы, высокая скорость записи;
- **графовые** (Neo4j) — связи и обходы графов.

Особенности NoSQL: гибкая схема, горизонтальное масштабирование из коробки, eventual consistency (часто BASE вместо ACID).

**CAP-теорема**: распределённая система может гарантировать только 2 из 3 — Consistency, Availability, Partition tolerance. При сетевом разделении выбор: CP (согласованность) или AP (доступность).

Выбор: сложные связи и транзакции — SQL; масштаб, гибкость схемы, специфические модели — NoSQL. Часто используют оба (polyglot persistence).`,
