        answer: `**INNER JOIN** — только строки, имеющие соответствие в обеих таблицах:

\`\`\`sql
SELECT * FROM orders o
INNER JOIN users u ON o.user_id = u.id;
\`\`\`

**LEFT (OUTER) JOIN** — все строки левой таблицы + совпадения из правой (иначе NULL):

\`\`\`sql
SELECT u.name, o.id FROM users u
LEFT JOIN orders o ON o.user_id = u.id; -- и пользователи без заказов
\`\`\`

**RIGHT (OUTER) JOIN** — зеркально LEFT JOIN: все строки правой таблицы.

**FULL (OUTER) JOIN** — все строки обеих таблиц, NULL там, где нет соответствия.

**CROSS JOIN** — декартово произведение: каждая строка с каждой.

**SELF JOIN** — соединение таблицы с самой собой (например, сотрудники и их менеджеры).

Дополнительно: \`LEFT JOIN ... WHERE right.id IS NULL\` — классический способ найти строки без соответствия (анти-джойн).`,
