        answer: `**GROUP BY** группирует строки по значениям столбцов, позволяя применять агрегатные функции (\`COUNT\`, \`SUM\`, \`AVG\`, \`MIN\`, \`MAX\`) к каждой группе:

\`\`\`sql
SELECT department, COUNT(*) AS cnt, AVG(salary) AS avg_salary
FROM employees
WHERE hire_date > '2020-01-01'   -- фильтр СТРОК (до группировки)
GROUP BY department
HAVING AVG(salary) > 50000       -- фильтр ГРУПП (после группировки)
ORDER BY avg_salary DESC;
\`\`\`

**Разница WHERE и HAVING:**

- **WHERE** фильтрует отдельные строки **до** группировки; не может использовать агрегатные функции;
- **HAVING** фильтрует группы **после** группировки; работает с агрегатами.

Логический порядок выполнения запроса: **FROM → JOIN → WHERE → GROUP BY → HAVING → SELECT → DISTINCT → ORDER BY → LIMIT**.

Правило: в SELECT при GROUP BY можно использовать только группируемые столбцы и агрегатные функции.`,
