        answer: `**Оконные функции** выполняют вычисления над набором строк («окном»), связанных с текущей строкой, **не сворачивая** строки (в отличие от GROUP BY).

\`\`\`sql
SELECT name, department, salary,
       ROW_NUMBER() OVER (PARTITION BY department ORDER BY salary DESC) AS rn,
       RANK()       OVER (ORDER BY salary DESC) AS rnk,
       AVG(salary)  OVER (PARTITION BY department) AS dept_avg,
       LAG(salary)  OVER (ORDER BY hire_date) AS prev_salary
FROM employees;
\`\`\`

Основные функции:

- **ранжирование**: \`ROW_NUMBER()\` (уникальные номера), \`RANK()\` (с пропусками), \`DENSE_RANK()\` (без пропусков), \`NTILE(n)\`;
- **смещение**: \`LAG()\`, \`LEAD()\` — предыдущая/следующая строка; \`FIRST_VALUE()\`, \`LAST_VALUE()\`;
- **агрегаты как оконные**: \`SUM() OVER (...)\` — накопительные суммы (running totals).

Элементы окна: \`PARTITION BY\` (разбиение), \`ORDER BY\` (порядок), frame (\`ROWS BETWEEN ...\`).

Классическая задача: «топ-3 зарплаты в каждом отделе» — через \`ROW_NUMBER() OVER (PARTITION BY ...)\` в подзапросе.`,
