        id: 'subqueries-cte',
        question: 'Что такое подзапросы и CTE (WITH)?',
        answer: `**Подзапрос** — запрос внутри другого запроса:

\`\`\`sql
-- скалярный
SELECT name FROM employees WHERE salary > (SELECT AVG(salary) FROM employees);

-- IN / EXISTS
SELECT * FROM users u WHERE EXISTS (
    SELECT 1 FROM orders o WHERE o.user_id = u.id
);

-- коррелированный (выполняется для каждой строки внешнего запроса)
SELECT name, (SELECT COUNT(*) FROM orders o WHERE o.user_id = u.id) FROM users u;
\`\`\`

**CTE (Common Table Expression)** — именованный временный результат через \`WITH\`:

\`\`\`sql
WITH dept_stats AS (
    SELECT department, AVG(salary) AS avg_sal
    FROM employees GROUP BY department
)
SELECT e.name, e.salary, d.avg_sal
FROM employees e JOIN dept_stats d ON e.department = d.department
WHERE e.salary > d.avg_sal;
\`\`\`

**Рекурсивные CTE** (\`WITH RECURSIVE\`) — обход иерархий (оргструктура, категории).

Преимущества CTE: читаемость, переиспользование в одном запросе, рекурсия. EXISTS обычно эффективнее IN на больших наборах; NOT IN опасен с NULL-значениями.`,
