        question: 'Какие виды тестирования вы знаете?',
        answer: `**По уровню (пирамида тестирования):**

- **Unit-тесты** — тестируют отдельный класс/метод в изоляции; быстрые, дешёвые, их больше всего (основание пирамиды);
- **Интеграционные тесты** — проверяют взаимодействие компонентов (с БД, очередями, внешними API); Testcontainers, @SpringBootTest;
- **E2E (end-to-end)** — тестируют всю систему через пользовательский интерфейс/API; медленные и хрупкие, их меньше всего.

**По цели:**

- функциональное / нефункциональное (нагрузочное, стресс, безопасность);
- регрессионное — проверка, что новое не сломало старое;
- smoke — базовая проверка работоспособности.

**По знанию внутренностей**: black-box / white-box / gray-box.

**Подходы**: TDD (test-driven development — тест до кода: red-green-refactor), BDD (behavior-driven: Given-When-Then, Cucumber).

Метрика: code coverage (JaCoCo), но 100% покрытие не гарантирует качество — важнее покрытие критической логики и граничных случаев.`,
