        id: 'log-levels',
        question: 'Какие уровни логирования существуют и когда их использовать?',
        answer: `Уровни (от подробного к критичному): **TRACE < DEBUG < INFO < WARN < ERROR** (+ FATAL в Log4j2).

- **TRACE** — максимально детальная трассировка: входы/выходы методов, итерации циклов. Только для глубокой отладки.
- **DEBUG** — отладочная информация: значения переменных, ветвления, SQL-запросы. Включается при диагностике.
- **INFO** — ключевые бизнес-события: старт приложения, обработка заказа, подключение к сервису. Стандартный уровень production.
- **WARN** — потенциальные проблемы, не мешающие работе: retry, deprecated API, приближение к лимитам, fallback.
- **ERROR** — ошибки, требующие внимания: необработанные исключения, отказ внешней системы, потеря данных.

Правила:

- установка уровня фильтрует всё «ниже»: уровень INFO скрывает DEBUG и TRACE;
- уровни настраиваются по пакетам: \`logging.level.org.hibernate.SQL=DEBUG\`;
- ERROR — только то, на что нужно реагировать (иначе алерты обесцениваются);
- не логировать чувствительные данные (пароли, токены, персональные данные).`,
