        answer: `**Диаграмма последовательности (Sequence Diagram)** показывает взаимодействие объектов во времени: какие сообщения, в каком порядке и между кем передаются.

Элементы:

- **участники (lifelines)** — объекты/акторы сверху, вертикальные пунктирные линии жизни вниз;
- **полоса активации** — прямоугольник на линии жизни: объект выполняет работу;
- **сообщения**:
  - сплошная стрелка с закрашенным наконечником — синхронный вызов;
  - сплошная стрелка с открытым наконечником — асинхронное сообщение;
  - пунктирная стрелка — возврат результата;
- **комбинированные фрагменты**: \`alt\` (if/else), \`opt\` (if), \`loop\` (цикл), \`par\` (параллельно), \`ref\` (ссылка на другую диаграмму);
- время течёт **сверху вниз**.

Пример (PlantUML):

\`\`\`
@startuml
actor User
User -> Controller : POST /orders
Controller -> Service : createOrder(dto)
Service -> Repository : save(order)
Repository --> Service : order
Service --> Controller : orderId
Controller --> User : 201 Created
@enduml
\`\`\`

Применение: документирование сценариев API, разбор сложных взаимодействий микросервисов, онбординг новых разработчиков.`,
