        answer: `**Основные селекторы:**

\`\`\`css
* { }                /* универсальный */
p { }                /* по тегу */
.card { }            /* по классу */
#header { }          /* по id */
[type="text"] { }    /* по атрибуту */

div p { }            /* потомок (любой уровень) */
div > p { }          /* прямой ребёнок */
h1 + p { }           /* следующий сосед */
h1 ~ p { }           /* все последующие соседи */

a:hover { }          /* псевдоклассы: :focus, :first-child, :nth-child(2n), :not() */
p::before { }        /* псевдоэлементы: ::after, ::first-line, ::placeholder */
\`\`\`

**Специфичность** — приоритет правил при конфликте, считается как (a, b, c):

- **a** — количество id-селекторов;
- **b** — классы, атрибуты, псевдоклассы;
- **c** — теги и псевдоэлементы.

\`#nav .item a\` = (1,1,1) побеждает \`.menu .item a\` = (0,2,1).

Инлайн-стили сильнее любых селекторов; \`!important\` перебивает всё (антипаттерн). При равной специфичности побеждает последнее правило (каскад). Рекомендация: держать специфичность низкой (методология BEM — только классы).`,
