        answer: `**static** (по умолчанию) — элемент в обычном потоке; top/left/z-index не работают.

**relative** — элемент в потоке, но смещается относительно **своей исходной позиции**; место в потоке сохраняется. Создаёт контекст для absolute-потомков.

**absolute** — элемент **изъят из потока**; позиционируется относительно ближайшего предка с position ≠ static (иначе — относительно \`<html>\`):

\`\`\`css
.parent { position: relative; }
.badge  { position: absolute; top: -8px; right: -8px; }
\`\`\`

**fixed** — изъят из потока; позиционируется относительно **окна браузера**, не двигается при скролле (шапки, модальные окна).

**sticky** — гибрид relative и fixed: элемент скроллится как обычно, но «прилипает» при достижении заданного порога:

\`\`\`css
.header { position: sticky; top: 0; }
\`\`\`

**z-index** — порядок наложения; работает только на позиционированных элементах (≠ static). Важно понятие **контекста наложения (stacking context)**: z-index сравнивается внутри одного контекста; новый контекст создают opacity < 1, transform, filter и др.`,
