        answer: `**Broker** — сервер Kafka, хранящий партиции и обслуживающий запросы продюсеров и консьюмеров. Кластер состоит из нескольких брокеров; партиции и их реплики распределяются между ними.

**Controller** — специальный брокер, координирующий кластер: назначает лидеров партиций, отслеживает состояние брокеров, управляет ребалансировкой реплик при сбоях.

**ZooKeeper → KRaft:** исторически Kafka хранила метаданные кластера (список брокеров, топики, лидеров) во внешнем **ZooKeeper**. Начиная с Kafka 2.8 и как стандарт в 3.x+, ZooKeeper заменён на **KRaft (Kafka Raft)** — метаданные хранятся в самой Kafka через встроенный Raft-консенсус. Плюсы KRaft: меньше движущихся частей (не нужен отдельный кластер ZooKeeper), быстрее восстановление и failover контроллера, лучше масштабируется по числу партиций.`,
