        answer: `Каждая партиция имеет **replication factor** — число копий на разных брокерах. Одна реплика — **лидер** (через неё идут все чтения и записи), остальные — **фолловеры**, которые копируют данные с лидера.

**ISR (In-Sync Replicas)** — множество реплик, «догнавших» лидера (не отставших больше допустимого). Только реплика из ISR может стать новым лидером.

**При падении лидера** контроллер выбирает нового лидера из ISR, и клиенты прозрачно переключаются на него — данные не теряются, если они были реплицированы в ISR. Настройка \`min.insync.replicas\` вместе с \`acks=all\` гарантирует, что запись подтверждается только после сохранения на нужном числе реплик: если живых ISR меньше \`min.insync.replicas\`, запись отклоняется (жертвуем доступностью ради сохранности). Если разрешить \`unclean.leader.election\`, лидером может стать отставшая реплика — это грозит потерей данных.`,
