        answer: `При повторной отправке (retry после таймаута, когда подтверждение потерялось, но сообщение на самом деле записалось) обычный продюсер может создать **дубликат** — семантика «at-least-once».

**Идемпотентный продюсер** (\`enable.idempotence=true\`, включён по умолчанию в новых версиях) устраняет дубликаты при повторах. Механизм: каждому продюсеру присваивается **Producer ID (PID)**, а каждому сообщению — монотонный **sequence number** на партицию. Брокер отслеживает последний записанный sequence и отбрасывает повторы с уже виденным номером.

Это даёт **exactly-once на уровне записи в одну партицию** в рамках сессии продюсера, без потери производительности. Для exactly-once **между несколькими партициями/топиками и в связке с консьюмером** нужны транзакции Kafka (см. вопрос про EOS). Идемпотентность автоматически подразумевает \`acks=all\`.`,
