        answer: `**Пропускную способность** повышают с нескольких сторон:

- **партиции** — основной рычаг параллелизма: больше партиций → больше консьюмеров в группе работают параллельно, выше суммарный throughput;
- **продюсер** — батчинг (\`batch.size\`, \`linger.ms\`), сжатие (\`compression.type\`: lz4/zstd), достаточный \`buffer.memory\`;
- **консьюмер** — обработка батчами, достаточный \`max.poll.records\`, параллелизм по партициям;
- **брокер/диски** — Kafka опирается на последовательную запись на диск и zero-copy; помогают быстрые диски и достаточная сеть.

**Число партиций — палка о двух концах.** Больше партиций = больше параллелизма, но:

- растут накладные расходы (открытые файлы, память, нагрузка на контроллер);
- дольше и «дороже» ребаланс и failover при сбоях;
- упорядоченность гарантируется только внутри партиции — больше партиций размывает глобальный порядок.

Число партиций легко увеличить, но **нельзя уменьшить**, и увеличение меняет распределение по ключам, поэтому его планируют заранее под целевую нагрузку.`,
