        id: 'kafka-streams-connect',
        question: 'Что такое Kafka Streams и Kafka Connect? В чём разница?',
        answer: `Это две отдельные библиотеки/фреймворка экосистемы Kafka для разных задач.

**Kafka Streams** — клиентская библиотека для **обработки потоков**: читает из топиков, трансформирует (map/filter/join/агрегации, оконные операции) и пишет результат обратно в Kafka. Работает как обычное Java-приложение (не отдельный кластер), хранит состояние локально (RocksDB) с бэкапом в compacted-топики, поддерживает EOS. Выбирают вместо «сырых» консьюмеров, когда нужна **stateful-обработка**: агрегации, джойны потоков, окна — иначе это пришлось бы писать вручную.

**Kafka Connect** — фреймворк для **интеграции Kafka с внешними системами** без написания кода, через готовые коннекторы:

- **source-коннекторы** тянут данные из внешних систем в Kafka (например, CDC из БД через Debezium);
- **sink-коннекторы** выгружают из Kafka во внешние системы (БД, Elasticsearch, S3).

Кратко: **Streams — обработка и трансформация** данных внутри Kafka; **Connect — перекладывание** данных между Kafka и внешним миром.`,
