        question: 'Что делать, если случайно закоммитил секреты (пароли, ключи)?',
        answer: `Главное сразу понять: если коммит **запушен**, секрет считается **скомпрометированным** — удаление из истории не отменяет того, что его могли увидеть или склонировать.

Порядок действий:

1. **Немедленно отозвать/сменить секрет** (ротация ключа, пароля, токена) — это первично и важнее чистки истории;
2. **убрать секрет из истории**, а не только из последнего коммита (иначе он останется в предыдущих). Инструменты: **\`git filter-repo\`** (рекомендуется) или BFG Repo-Cleaner — они переписывают историю, удаляя файл/строку из всех коммитов;
3. если ветка общая — договориться с командой: переписывание истории требует **force-push** и повторного клонирования у всех;
4. **не допускать повторения**: хранить секреты в переменных окружения / менеджерах секретов (Vault), добавить файлы в \`.gitignore\`, включить сканеры секретов (git-secrets, gitleaks) в pre-commit и CI.

Ключевая мысль: ротация секрета обязательна всегда; чистка истории — лишь дополнение, снижающее дальнейшую утечку.`,
