        question: 'Какие способы взаимодействия между микросервисами существуют?',
        answer: `**Синхронное взаимодействие** (запрос-ответ, вызывающий ждёт):

- **REST/HTTP + JSON** — простота, универсальность; стандарт для внешних API;
- **gRPC** — бинарный Protobuf, HTTP/2, строгие контракты, стриминг; в 5-10 раз быстрее REST — выбор для межсервисного общения;
- **GraphQL** — гибкие выборки, обычно на BFF/API Gateway.

Минусы синхронного: каскадные отказы (сервис ждёт сервис, который ждёт сервис...), временнáя связанность (оба должны быть доступны).

**Асинхронное взаимодействие** (через брокер сообщений):

- **события** (Kafka, RabbitMQ): сервис публикует «OrderCreated», подписчики реагируют независимо;
- **команды/очереди задач**: точечная доставка одному исполнителю;
- плюсы: слабая связанность, буферизация нагрузки, устойчивость к недоступности потребителя;
- минусы: eventual consistency, сложнее отладка, дубликаты (нужна идемпотентность).

**Ключевые практики:**

- **API-контракты**: OpenAPI/Protobuf схемы, contract testing (Pact), обратная совместимость;
- **service discovery**: Kubernetes DNS, Eureka, Consul;
- **устойчивость**: таймауты, ретраи с backoff, circuit breaker (Resilience4j);
- **наблюдаемость**: распределённый трейсинг (OpenTelemetry, correlation id).

Рекомендация: события для интеграции доменов, синхронные вызовы — для запросов данных в реальном времени.`,
