        question: 'Что такое AWS и в чём разница между IaaS, PaaS и SaaS?',
        answer: `**AWS (Amazon Web Services)** — облачная платформа, предоставляющая вычисления, хранилище, сети, базы данных и другие сервисы по модели **оплаты за использование** (pay-as-you-go), без покупки собственного железа.

Три модели облачных услуг различаются тем, **что управляет провайдер, а что вы**:

- **IaaS (Infrastructure as a Service)** — провайдер даёт «сырую» инфраструктуру (виртуальные машины, сеть, диски), вы управляете ОС, рантаймом и приложением. Максимум контроля и гибкости. Пример: **EC2**, EBS, VPC.
- **PaaS (Platform as a Service)** — провайдер управляет ОС и рантаймом, вы деплоите только код и данные. Меньше рутины, быстрее разработка. Пример: **Elastic Beanstalk**, RDS, App Runner.
- **SaaS (Software as a Service)** — готовое приложение «под ключ», вы просто пользуетесь им через браузер. Пример: Gmail, Office 365, Salesforce (в AWS — например, WorkMail).

Аналогия: IaaS — арендовать землю и строить дом самому; PaaS — арендовать дом; SaaS — жить в отеле. Чем выше уровень, тем меньше управления, но и меньше контроля. Отдельно стоит **serverless (FaaS)** — например, Lambda, где не управляют даже серверами.`,
