        answer: `**IAM (Identity and Access Management)** — сервис управления доступом к ресурсам AWS: **кто** (аутентификация) и **что может делать** (авторизация). Базовый принцип — **least privilege** (минимально необходимые права).

Ключевые сущности:

- **User (пользователь)** — постоянная идентичность человека или приложения с долгосрочными учётными данными (пароль, access keys). Можно объединять в **группы** и назначать права группе.
- **Role (роль)** — идентичность с **временными** правами, которую можно «примерить» (assume). У роли **нет постоянных ключей** — выдаются временные токены (STS). Роли — предпочтительный способ: их берут на себя EC2-инстансы, Lambda, сервисы, федеративные пользователи. Безопаснее, чем раздавать долгосрочные ключи.
- **Policy (политика)** — JSON-документ, описывающий **разрешения** (Effect Allow/Deny, Action, Resource, Condition). Прикрепляется к пользователю, группе или роли.
- **MFA (Multi-Factor Authentication)** — дополнительный фактор (одноразовый код с телефона/устройства) поверх пароля. Обязательна для привилегированных аккаунтов (root, админы).

Правило: приложениям и сервисам давать **роли**, а не зашитые ключи; людям — пользователей с MFA; права — через политики по принципу минимальных привилегий.`,
