        answer: `**KMS (Key Management Service)** — управляемый сервис для создания и управления **ключами шифрования** и выполнения криптоопераций. Он хранит **мастер-ключи (CMK / KMS keys)**, которые никогда не покидают сервис в открытом виде, и контролирует доступ к ним через IAM-политики и audit-логи (CloudTrail).

Как обычно применяется — **envelope encryption (конвертное шифрование)**: KMS-ключом шифруется не сами данные, а сгенерированный **data key**, которым уже шифруются большие данные. Так быстро и безопасно шифруются большие объёмы, а в хранилище лежит зашифрованный data key.

Где используется:

- **шифрование покоящихся данных (at rest)** в других сервисах: S3 (SSE-KMS), EBS-тома, RDS, DynamoDB, снапшоты — интеграция «из коробки»;
- шифрование секретов в **Secrets Manager** / SSM Parameter Store;
- прикладное шифрование через SDK;
- контроль и **ротация** ключей, разграничение доступа, полный аудит использования.

Плюсы: ключи под контролем и аудитом, не хранятся в коде; можно задать автоматическую ротацию. Для аппаратной изоляции высшего уровня есть **CloudHSM**.`,
