        answer: `Три сервиса — три разных типа хранения:

- **S3 (Simple Storage Service)** — **объектное** хранилище: файлы («объекты») в бакетах, доступ по HTTP API/URL. Практически безграничное, очень надёжное (11 «девяток» durability), не привязано к конкретному инстансу. Для: файлов, бэкапов, статики сайтов, data lake, медиа. Не является файловой системой и не монтируется как диск.
- **EBS (Elastic Block Store)** — **блочное** хранилище: виртуальный диск, **подключаемый к одному EC2-инстансу** (как HDD/SSD). Данные переживают перезапуск инстанса, поддерживает снапшоты. Для: корневых томов ОС, БД на EC2, всего, что требует диска с низкой задержкой. Привязан к одной AZ.
- **Glacier (S3 Glacier)** — **архивное** хранилище: очень дёшево, но с **задержкой доступа** (от минут до часов в зависимости от класса извлечения). Для: долгосрочных архивов, комплаенса, редко читаемых данных.

Кратко: **S3** — объекты и файлы (общий доступ, масштаб); **EBS** — диск для одного инстанса (низкая задержка); **Glacier** — дешёвый холодный архив. У S3 есть классы (Standard, IA, Intelligent-Tiering, Glacier) с автоматическим перемещением данных по lifecycle-политикам.`,
