        answer: `**RDS** — управляемая **реляционная** БД (SQL): таблицы со схемой, связи, JOIN, транзакции ACID, сложные запросы. **DynamoDB** — управляемая **NoSQL** key-value / документная БД: без схемы, горизонтально масштабируется, предсказуемая низкая задержка на любом объёме, оплата по запросам/ёмкости.

**Выбирайте RDS, когда:**

- данные **реляционные**, много связей, нужны JOIN и сложные ad-hoc запросы;
- важны строгие **ACID-транзакции** (финансы);
- схема стабильна, объёмы умеренные, знакомый SQL.

**Выбирайте DynamoDB, когда:**

- нужен **огромный масштаб** и стабильно низкая задержка (single-digit ms) при любом росте;
- доступ **по ключу** и заранее известные паттерны запросов (моделируют «от запросов»);
- гибкая/меняющаяся схема, высокая нагрузка на запись, serverless-стек;
- не хочется управлять шардированием и капасити вручную (есть on-demand режим).

Ограничения DynamoDB — нет полноценных JOIN и сложных запросов «на лету», нужно продумывать ключи и индексы (GSI/LSI) под доступ заранее. Правило: реляционная модель и сложные запросы → **RDS**; предсказуемый доступ по ключу с гипермасштабом → **DynamoDB**. Часто их сочетают в одной системе.`,
