        answer: `**CIDR (Classless Inter-Domain Routing)** задаёт диапазон IP-адресов сети через маску: например, VPC \`10.0.0.0/16\` (65 536 адресов), а подсеть \`10.0.1.0/24\` (256 адресов). Число после \`/\` — сколько бит фиксировано под сеть: чем оно больше, тем меньше адресов.

**Подсети (subnets)** — сегменты VPC внутри одной AZ. Публичность определяется **таблицей маршрутизации**:

- **Public subnet** — в её route table есть маршрут в **Internet Gateway (IGW)**. IGW — компонент VPC, дающий двунаправленный доступ в интернет. Сюда помещают то, что должно быть доступно извне: load balancer, bastion, публичные веб-серверы (у них есть public IP).
- **Private subnet** — маршрута в IGW нет, из интернета напрямую недоступна. Сюда помещают приложения и **БД** (безопаснее).

**NAT Gateway** решает задачу: приватным ресурсам нужен **исходящий** доступ в интернет (скачать обновления, вызвать внешний API), но **входящий** — нельзя. NAT размещают в **публичной** подсети; приватные ресурсы через маршрут в NAT ходят наружу, а снаружи инициировать соединение к ним нельзя.

Типичная схема: LB и NAT — в public-подсетях; серверы приложений и БД — в private; трафик режут Security Groups и NACL.`,
