        answer: `При **network partition** узлы теряют связь друг с другом и не могут согласовать данные. Система вынуждена выбрать одно из двух:

- сохранить **консистентность (CP)** — отклонять запросы к узлам, которые не могут подтвердить актуальность данных; часть системы становится временно недоступной;
- сохранить **доступность (AP)** — продолжать отвечать локальными данными, приняв риск рассогласования, а после восстановления связи разрешать конфликты (last-write-wins, векторные часы, CRDT).

Выбор определяется требованиями бизнеса: для платежей важнее консистентность, для ленты соцсети — доступность. После восстановления связи узлы синхронизируются (anti-entropy, read repair).`,
