        answer: `**Шардирование (партиционирование)** — горизонтальное разбиение данных на части (шарды), размещённые на разных узлах, чтобы масштабировать объём и нагрузку. **Shard key** определяет, на какой шард попадёт запись.

Хороший ключ:

- обеспечивает **равномерное** распределение данных и нагрузки между шардами;
- соответствует частым запросам, чтобы запрос шёл в один шард, а не во все сразу.

**Hot key / hot partition** — ситуация, когда один ключ или диапазон получает непропорционально много запросов. Классический пример — шардирование по дате: вся свежая запись идёт в один шард. Лечится выбором более равномерного ключа, хешированием или составными ключами.`,
