        question: 'Чем моделирование данных в NoSQL отличается от нормализации в SQL? Embedding или referencing?',
        answer: `В SQL данные **нормализуют** — разбивают на таблицы без дублирования, а связи собирают через JOIN. В NoSQL моделируют **от запросов** (query-driven) и осознанно **денормализуют** — дублируют данные, чтобы читать их одним запросом.

**Embedding (вложение)** — хранить связанные данные внутри документа. Плюс: одно чтение и атомарность на документ. Минус: рост документа и дублирование. Выбирают при отношении «содержит» и данных, читаемых вместе (заказ + его позиции).

**Referencing (ссылка)** — хранить id и подгружать связанное отдельно. Выбирают при связях many-to-many и больших или независимо изменяемых данных.

Привычных JOIN нет — их заменяют денормализацией, материализованными представлениями или join на стороне приложения.`,
