        id: 'nosql-transactions',
        question: 'Как в NoSQL обстоят дела с транзакциями и атомарностью? Что такое upsert?',
        answer: `Обычно гарантируется атомарность на уровне **одного документа / строки / ключа**: операция над одним документом либо применяется целиком, либо не применяется. Это следствие денормализации — связанные данные лежат вместе.

**Multi-document транзакции** существуют (например, в MongoDB начиная с 4.0), но стоят дороже: выше latency, нужна координация между шардами, есть ограничения — поэтому их избегают на горячих путях.

**Upsert** — «обнови, если запись есть, иначе вставь» (update-or-insert). Удобно, но при конкурентных запросах возможны гонки: два upsert могут создать дубликаты или перезаписать друг друга. Защита — уникальные индексы, атомарные операторы (\`$setOnInsert\`) и оптимистичные блокировки по версии.`,
