        id: 'caching-strategies',
        question: 'Redis как кэш: какие стратегии кэширования бывают и какие у кэша проблемы?',
        answer: `**Стратегии кэширования:**

- **Cache-aside (lazy loading)** — приложение сначала смотрит в кэш; при промахе читает БД и кладёт результат в кэш. Самая частая. Минус: первый запрос медленный, возможна рассинхронизация с БД.
- **Write-through** — запись идёт в кэш и синхронно в БД. Кэш всегда актуален, но запись медленнее.
- **Write-behind (write-back)** — запись в кэш, а в БД асинхронно позже. Быстрая запись, но риск потери данных при сбое.

**TTL** (time-to-live) — время жизни записи в кэше, по истечении которого она удаляется; защищает от бесконечного роста и устаревших данных.

**Проблемы кэша:**

- **Cache stampede** — по истечении TTL популярного ключа множество запросов одновременно бьют в БД. Лечится блокировкой на перегенерацию и разбросом TTL (jitter).
- **Cache penetration** — запросы на заведомо несуществующие ключи всегда проходят в БД. Лечится кэшированием «пустого» ответа или Bloom-фильтром.
- **Cache avalanche** — массовое одновременное истечение множества ключей роняет БД. Лечится разбросом TTL.`,
