        answer: `**Чистый код** — код, который **легко читать, понимать и изменять** другим людям (и вам через полгода). Ключевая идея: код читают **гораздо чаще**, чем пишут, поэтому оптимизировать надо под чтение.

Почему это важно:

- большую часть жизни ПО занимает **сопровождение** — чтение и правка, а не первое написание;
- грязный код замедляет команду: каждое изменение рискованно и требует «раскопок»;
- **технический долг** накапливается — «мы поправим потом» превращается в систему, которую страшно трогать.

Признаки чистого кода: осмысленные имена, маленькие функции с одной задачей, минимум дублирования, явная обработка ошибок, отсутствие «умного» запутанного кода, читаемость важнее краткости.

Ориентиры-первоисточники: **«Чистый код» (Роберт Мартин)** — про читаемость и структуру на уровне имён/функций/классов, и **«Effective Java» (Джошуа Блох)** — про идиомы и best practices именно Java (иммутабельность, дженерики, исключения). Обе дополняют принципы **SOLID/DRY/KISS** (см. раздел «Шаблоны проектирования»): SOLID — про структуру, чистый код — про повседневную читаемость.`,
