        answer: `Главный принцип: **комментарий объясняет «почему», а не «что»**. Что делает код, должен показывать **сам код** (через хорошие имена и структуру), а не комментарий-пересказ.

**Плохие (лишние) комментарии:**

- дублируют код: \`i++; // увеличиваем i\` — шум;
- **закомментированный код** — его надо удалять (история есть в git), а не хранить;
- **устаревшие** комментарии, разошедшиеся с кодом, — хуже, чем их отсутствие: они врут;
- комментарии как «костыль» для плохого кода: вместо комментария к непонятному фрагменту лучше его **переписать/переименовать**.

**Полезные комментарии:**

- объяснение **намерения и причины** решения («почему именно так, а не очевидным способом»);
- предупреждение о последствиях/неочевидных ограничениях (потокобезопасность, порядок вызовов, обход бага библиотеки);
- **TODO/FIXME** с контекстом;
- документация публичного API (**Javadoc**) — контракт метода для внешних потребителей;
- пояснение к сложной формуле/регулярному выражению/алгоритму.

Правило: сначала попытаться выразить мысль **кодом** (имя переменной/метода, выделение функции), и только то, что код выразить не может (причину, контекст), — комментарием.`,
